    @SerialName("mechanics") val mechanics: Double,
    @SerialName("utility") val utility: Double,
    @SerialName("preparation") val preparation: Double,
    @SerialName("activity") val activity: Double,
)

/** One cast of the sample iteration. */
@Serializable
data class SampleCast(
    /** Negative during the pre-pull, which the page renders as its own section. */
    @SerialName("at_ms") val atMs: Long,
    /** The summary's action key - "spell:23881", "item:13503", "other:attack" - and not a display name; it is resolved to a name the same way a cast row is. */
    @SerialName("action") val action: String,
    @SerialName("target") val target: String? = null,
    /** What the player held AFTER the cast: rage, energy, mana, combo_points. */
    @SerialName("resources") val resources: Map<String, Int>? = null,
)

@Serializable
data class ScoreComponents(
    @SerialName("gear") val gear: Int,
    @SerialName("experience") val experience: Int,
    @SerialName("parses") val parses: Int,
    @SerialName("attendance") val attendance: Int,
    @SerialName("discipline") val discipline: Int,
)

@Serializable
data class ScoreExperience(
    @SerialName("dungeons") val dungeons: Int,
    @SerialName("raid_kills") val raidKills: Int,
    @SerialName("alts") val alts: Int,
)

/** One UTC date of score_history on GET /v1/characters/{region}/{ruleset}/{name}: the Forever Score the rater recorded on the last rated fight of that date. The list has one point per date on which a rated fight in a public, unflagged report landed, the newest 30 dates, oldest first; [] when there is none. Fights rated before the score's snapshot existed (migration 0035), or re-rated by the backfill, carry no snapshot and are left out. */
@Serializable
data class ScorePoint(
    /** The UTC date, YYYY-MM-DD. */
    @SerialName("date") val date: String,
    @SerialName("score") val score: Int,
    @SerialName("tier") val tier: String,
)

/** Omitted when the server has no sims store configured. */
@Serializable
data class ServerSimsUsage(
    @SerialName("runs_this_month") val runsThisMonth: Int,
)

@Serializable
data class SignedOut(
    @SerialName("signed_out") val signedOut: Boolean,
)

@Serializable
data class SignupAnswer(
    @SerialName("raid") val raid: RaidView,
    /** Your other character the server moved to Bench; tell the player. */
    @SerialName("moved") val moved: String? = null,
)

@Serializable
data class SignupRequest(
    @SerialName("state") val state: String,
    /** Empty takes the spec's default. */
    @SerialName("role") val role: String? = null,
    /** The PUT writes note; leaving it out clears the stored note. */
    @SerialName("note") val note: String? = null,
    /** A specs.json key such as "warrior-fury", saved as the raid spec first. */
    @SerialName("spec") val spec: String? = null,
)

/** The character model a sim starts from. gear is the FS1 export string for an export (source addon or blizzard) and { trinkets } for a fight: branch on source, not on the shape. */
@Serializable
data class SimInput(
    @SerialName("spec") val spec: String,
    @SerialName("spec_source") val specSource: String,
    @SerialName("gear") val gear: JsonElement,
    @SerialName("talents") val talents: String,
    @SerialName("buffs") val buffs: List<String> = emptyList(),
    @SerialName("captured_at") val capturedAt: String,
    @SerialName("source") val source: String,
)

@Serializable
data class SimList(
    @SerialName("rows") val rows: List<SimRow> = emptyList(),
    @SerialName("total") val total: Int,
    @SerialName("page") val page: Int,
    @SerialName("per_page") val perPage: Int,
)

/** Poll every 2 seconds; stop at done or error. */
@Serializable
data class SimProgress(
    @SerialName("state") val state: String,
    @SerialName("iterations_done") val iterationsDone: Int,
    /** Omitted until running or done. */
    @SerialName("dps") val dps: Double? = null,
    @SerialName("stage") val stage: Int,
    @SerialName("combos_done") val combosDone: Int,
    @SerialName("combos_total") val combosTotal: Int,
)

@Serializable
data class SimRequest(
    /** The short sha of the engine build, from sim/enginever. */
    @SerialName("engine_version") val engineVersion: String,
    @SerialName("spec") val spec: String,
    @SerialName("source") val source: SimRequestSource,
    @SerialName("character") val character: SimRequestCharacter,
    @SerialName("encounter") val encounter: SimRequestEncounter,
    @SerialName("iterations") val iterations: Int,
    @SerialName("random_seed") val randomSeed: Long? = null,
    /** Turns one character into many sims. A request carrying it is a gear, talents or drops request, by bulk.mode; one carrying weights instead is a weights request; one carrying neither is a plain run. A request never names its own kind, and never carries both blocks. */
    @SerialName("bulk") val bulk: BulkSpec? = null,
    /** Asks for stat weights instead of a DPS number. */
    @SerialName("weights") val weights: WeightsSpec? = null,
    /** Asks a healer or tank spec's plain run for the figure its role is ranked on. A healer runs against the curated heal profile's fake raid for the profile's fixed fight (duration_sec and variation are replaced) and the result carries healing; a tank runs in the curated boss fight it always does and the result carries tank. A damage spec, a bulk request and a weights request refuse it. */
    @SerialName("role_metrics") val roleMetrics: Boolean? = null,
)

@Serializable
data class SimRequestCharacter(
    @SerialName("name") val name: String? = null,
    @SerialName("race") val race: String,
    @SerialName("class") val className: String,
    @SerialName("level") val level: Int,
    /** The engine's own positional talent string. */
    @SerialName("talents") val talents: String? = null,
    @SerialName("gear") val gear: List<GearSlot>? = null,
    @SerialName("buffs") val buffs: List<String>? = null,
    @SerialName("consumes") val consumes: List<String>? = null,
    @SerialName("professions") val professions: List<String>? = null,
)

@Serializable
data class SimRequestEncounter(
    @SerialName("duration_sec") val durationSec: Int? = null,
    @SerialName("variation") val variation: Double? = null,
    @SerialName("targets") val targets: Int? = null,
    @SerialName("execute_ratio") val executeRatio: Double? = null,
    @SerialName("profile") val profile: String? = null,
)

@Serializable
data class SimRequestSource(
    @SerialName("kind") val kind: String? = null,
    @SerialName("ref") val ref: String? = null,
    @SerialName("captured_at") val capturedAt: String? = null,
)

@Serializable
data class SimResult(
    @SerialName("sim_id") val simId: String? = null,
    /** The run's saved title; omitted when it has none. */
    @SerialName("title") val title: String? = null,
    @SerialName("engine_version") val engineVersion: String,
    @SerialName("request") val request: SimRequest? = null,
    @SerialName("lane") val lane: String,
    @SerialName("dps") val dps: Estimate,
    @SerialName("iterations_run") val iterationsRun: Int,
    @SerialName("duration_ms") val durationMs: Long? = null,
    /** The logs engine's per-fight summary, so the report components render a sim. */
    @SerialName("summary") val summary: JsonElement? = null,
    @SerialName("error") val error: String? = null,
    /** The run was stopped on request rather than failing; iterations_run is whatever completed. Never true on a saved result - POST /v1/sims refuses one. */
    @SerialName("aborted") val aborted: Boolean? = null,
    /** The ranked answer to a bulk request, best first. */
    @SerialName("combos") val combos: List<Combo>? = null,
    /** The base character at the FINAL stage, which is what every combo's delta is measured against. Absent, rather than zero, when there is no baseline. */
    @SerialName("equipped") val equipped: Estimate? = null,
    /** What the planner actually ran, so the page can say "3 stages, 38 combinations" without recomputing the ladder. */
    @SerialName("stages") val stages: List<Stage>? = null,
    /** The answer to a weights request. */
    @SerialName("weights") val weights: List<StatWeight>? = null,
    /** One iteration's casts in order - the median-DPS one. It is a table view of the cast log, not a guide. */
    @SerialName("sample") val sample: List<SampleCast>? = null,
    @SerialName("healing") val healing: HealingResult? = null,
    @SerialName("tank") val tank: TankResult? = null,
)

@Serializable
data class SimRow(
    @SerialName("sim_id") val simId: String? = null,
    @SerialName("spec") val spec: String? = null,
    @SerialName("kind") val kind: String? = null,
    @SerialName("dps") val dps: Double? = null,
    /** The one line the history list shows, composed when the result was written: "1,204 DPS", "+41 DPS from Vis'kag the Bloodletter", "3 upgrades on Ragnaros", "+18 DPS with 'Deep Fury'", "Crit 1.00 · Agility 0.87". */
    @SerialName("headline") val headline: String? = null,
    /** The row's own state. A failed run has no headline to show, and without this the page could not tell that from a row whose headline is simply missing. */
    @SerialName("state") val state: String? = null,
    @SerialName("engine_version") val engineVersion: String? = null,
    @SerialName("created_at") val createdAt: String? = null,
    @SerialName("title") val title: String? = null,
    /** Where the run happened. */
    @SerialName("lane") val lane: String? = null,
    /** When a server run reached done or error. Absent while it is queued or running, and for a browser save. */
    @SerialName("finished_at") val finishedAt: String? = null,
    /** The plain sentence a failed run stopped with. Absent unless state is error. */
    @SerialName("failure_reason") val failureReason: String? = null,
    /** Whether the owner has looked at the finished result. */
    @SerialName("seen") val seen: Boolean? = null,
    /** How long a run of this spec usually takes: the median of the last ten finished server runs. Only on queued and running rows, and absent with fewer than three finished runs. */
    @SerialName("estimate_seconds") val estimateSeconds: Int? = null,
)

@Serializable
data class SimStarted(
    /** The new run. */
    @SerialName("sim_id") val simId: String,
)

/** One rung of the ladder, as run. */
@Serializable
data class Stage(
    @SerialName("iterations") val iterations: Int,
    @SerialName("combos") val combos: Int,
)

/** One stat's answer. The reference stat's weight is exactly 1. */
@Serializable
data class StatWeight(
    @SerialName("stat") val stat: String,
    @SerialName("weight") val weight: Double,
    @SerialName("error") val error: Double,
)

/** One change from the base character. */
@Serializable
data class Substitution(
    @SerialName("kind") val kind: String,
    /** Where an item landed. A ring or a trinket says which of the two slots it took, because that is the answer the player acts on. */
    @SerialName("slot") val slot: String? = null,
    @SerialName("item_id") val itemId: Int? = null,
    @SerialName("enchant") val enchant: Int? = null,
    @SerialName("suffix") val suffix: Int? = null,
    /** The item's, the loadout's or the set's name. An item's name is filled in from the engine's own item database, so a row read back years later still says what it was about. For a consumes substitution it is the consumable ids joined by ", ", or "no consumables" when the alternative list is empty. */
    @SerialName("name") val name: String? = null,
    @SerialName("talents") val talents: String? = null,
    /** Copied from the candidate. */
    @SerialName("origin") val origin: String? = null,
    /** Copied from the candidate; a Droptimizer headline reads it. */
    @SerialName("source_name") val sourceName: String? = null,
    /** The alternative consumable list this combination ran. */
    @SerialName("consumes") val consumes: List<String>? = null,
)

@Serializable
data class Talent(
    @SerialName("id") val id: Int,
    @SerialName("name") val name: String,
    @SerialName("icon") val icon: String,
    @SerialName("max_rank") val maxRank: Int,
    @SerialName("tier") val tier: Int,
    @SerialName("column") val column: Int,
    @SerialName("prereq_talent_id") val prereqTalentId: Int? = null,
    @SerialName("prereq_rank") val prereqRank: Int? = null,
    @SerialName("spell_id") val spellId: Int,
    @SerialName("ranks") val ranks: List<TalentRank> = emptyList(),
)

/** One named build to try. */
@Serializable
data class TalentLoadout(
    @SerialName("name") val name: String,
    /** The engine's own positional talent string. */
    @SerialName("talents") val talents: String,
)

@Serializable
data class TalentRank(
    @SerialName("spell_id") val spellId: Int,
    @SerialName("description") val description: String,
)

@Serializable
data class TalentsFile(
    @SerialName("build") val build: String,
    @SerialName("class_id") val classId: Int,
    @SerialName("class_slug") val classSlug: String,
    @SerialName("trees") val trees: List<TalentTree> = emptyList(),
)

@Serializable
data class TalentTree(
    @SerialName("id") val id: Int,
    @SerialName("name") val name: String,
    @SerialName("position") val position: Int,
    @SerialName("background") val background: String,
    @SerialName("icon") val icon: String,
    @SerialName("talents") val talents: List<Talent> = emptyList(),
)

/** What a tank took and made against the curated boss and the score made of it (sim/score); present only when the request set role_metrics for a tank spec. */
@Serializable
data class TankResult(
    @SerialName("dtps") val dtps: Estimate,
    @SerialName("tps") val tps: Estimate,
    @SerialName("tmi") val tmi: Estimate,
    /** The character's maximum health. */
    @SerialName("health") val health: Double,
    /** The hit points the boss's raw damage would take to kill the tank at the damage it actually takes. */
    @SerialName("effective_health") val effectiveHealth: Double,
    @SerialName("chance_of_death") val chanceOfDeath: Double,
    /** The tank score. A bulk-pooled run computes it after pooling the three measured terms, because it is nonlinear in them. */
    @SerialName("score") val score: Estimate,
)

/** Asks for stat weights instead of a DPS number. */
@Serializable
data class WeightsSpec(
    /** Engine stat ids: the Stat enum names in lower snake case - attack_power, crit, spell_haste. There is no melee_crit or spell_crit; the engine carries one hit and one crit. A stat the engine does not have is refused rather than weighed as nothing. */
    @SerialName("stats") val stats: List<String> = emptyList(),
    /** The stat normalised to exactly 1.0. It is required and must be one of stats: a reference that is not among the stats being weighed would normalise against a number nobody computed. The per-spec default is reference_stat on GET /v1/specs. */
    @SerialName("reference") val reference: String,
)
